require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/public_nav_v1100.php';$u=current_user();if(!$u||!(has_permission('settings.manage',$u)||has_permission('updates.manage',$u)||has_permission('tenants.manage',$u))){http_response_code(403);exit('Forbidden');}$tid=spn1100_tid();$msg='';$err='';$core=spn1100_core_routes();try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='save'){foreach(($_POST['item']??[]) as $key=>$v){if(!is_array($v))continue;$key=spn1100_key($key);$url=trim((string)($v['url']??''));if(isset($core[$key])){$url=$core[$key];$group='primary';$parent='';$enabled=1;$priority='primary';}else{$group=in_array(($v['group_key']??'primary'),['primary','account','footer'],true)?$v['group_key']:'primary';$parent=spn1100_key((string)($v['parent_key']??''));$enabled=!empty($v['enabled'])?1:0;$priority=in_array(($v['priority']??'secondary'),['primary','secondary'],true)?$v['priority']:'secondary';}if(!$key||!spn1100_safe_url($url))continue;$sql='INSERT INTO public_navigation_rules_v1100(tenant_id,nav_key,label,url,group_key,parent_key,priority,sort_order,enabled,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE label=VALUES(label),url=VALUES(url),group_key=VALUES(group_key),parent_key=VALUES(parent_key),priority=VALUES(priority),sort_order=VALUES(sort_order),enabled=VALUES(enabled),updated_by=VALUES(updated_by),updated_at=NOW()';db()->prepare($sql)->execute([$tid,$key,mb_substr(trim((string)($v['label']??$key)),0,120),$url,$group,$parent,$priority,(int)($v['sort_order']??100),$enabled,(int)$u['id']]);}$msg='Landing menu saved. Core main-menu URLs were kept canonical.';}elseif($a==='repair_core'){$keys=array_keys($core);$ph=implode(',',array_fill(0,count($keys),'?'));$q=db()->prepare('DELETE FROM public_navigation_rules_v1100 WHERE tenant_id=? AND nav_key IN ('.$ph.')');$q->execute(array_merge([$tid],$keys));foreach(['my_shahkot','ask_shahkotpk','business_leads','deals','compare','wallet','favorites','referrals','my_bookings','notifications','community'] as $key){db()->prepare('DELETE FROM public_navigation_rules_v1100 WHERE tenant_id=? AND nav_key=?')->execute([$tid,$key]);}$msg='Canonical public navigation repaired. Home, main links and dropdown children restored.';}elseif($a==='restore'){db()->prepare('DELETE FROM public_navigation_rules_v1100 WHERE tenant_id=?')->execute([$tid]);$msg='All landing menu overrides restored to canonical v11.0.2 defaults.';}}}catch(Throwable $e){$err=$e->getMessage();}$items=spn1100_items();$parents=array_filter($items,fn($x)=>empty($x['parent_key'])&&$x['group_key']==='primary');page_start('Landing Menu Manager',true);?><link rel="stylesheet" href="/assets/admin-ai-copilot-v1100.css?v=1102"><div class="ai1100-admin"><section class="hero"><div><span>PUBLIC NAVIGATION · v11.0.2</span><h1>Landing Menu Manager</h1><p>Canonical main menu: Home, Businesses, Marketplace, Property, Health and Events. Related customer pages stay inside those dropdowns.</p></div></section><?php if($msg):?><div class="notice ok"><?=spn1100_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=spn1100_h($err)?></div><?php endif;?><section class="panel"><h2>Navigation repair</h2><p>If Home opens the wrong page, a dropdown is empty or duplicate arrows appear, use this safe repair. Custom non-canonical links are not deleted.</p><form method="post"><input type="hidden" name="_csrf" value="<?=spn1100_h(csrf_token())?>"><button name="action" value="repair_core">Repair Canonical Main Menu</button></form></section><form method="post"><input type="hidden" name="_csrf" value="<?=spn1100_h(csrf_token())?>"><input type="hidden" name="action" value="save"><section class="panel"><h2>All public pages</h2><?php foreach($items as $x):$locked=isset($core[$x['nav_key']]);?><div class="grid" style="padding:12px 0;border-bottom:1px solid #eef1f5"><label>Label<input name="item[<?=spn1100_h($x['nav_key'])?>][label]" value="<?=spn1100_h($x['label'])?>"></label><label>URL<input name="item[<?=spn1100_h($x['nav_key'])?>][url]" value="<?=spn1100_h($x['url'])?>" <?=$locked?'readonly':''?>></label><label>Menu<select name="item[<?=spn1100_h($x['nav_key'])?>][group_key]" <?=$locked?'disabled':''?>><?php foreach(['primary'=>'Header','account'=>'Account / Quick access','footer'=>'Footer'] as $k=>$l):?><option value="<?=$k?>" <?=$x['group_key']===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Under page<select name="item[<?=spn1100_h($x['nav_key'])?>][parent_key]" <?=$locked?'disabled':''?>><option value="">Main menu</option><?php foreach($parents as $p):if($p['nav_key']===$x['nav_key'])continue;?><option value="<?=spn1100_h($p['nav_key'])?>" <?=($x['parent_key']??'')===$p['nav_key']?'selected':''?>><?=spn1100_h($p['label'])?></option><?php endforeach;?></select></label><label>Order<input type="number" name="item[<?=spn1100_h($x['nav_key'])?>][sort_order]" value="<?=(int)$x['sort_order']?>"></label><label>Priority<select name="item[<?=spn1100_h($x['nav_key'])?>][priority]" <?=$locked?'disabled':''?>><option value="primary" <?=$x['priority']==='primary'?'selected':''?>>Primary</option><option value="secondary" <?=$x['priority']==='secondary'?'selected':''?>>Secondary</option></select></label><label class="check"><input type="checkbox" name="item[<?=spn1100_h($x['nav_key'])?>][enabled]" value="1" <?=$x['enabled']?'checked':''?> <?=$locked?'disabled':''?>> Show<?=$locked?' (core)':''?></label></div><?php endforeach;?><button style="margin-top:14px">Save Menu</button></section></form><form method="post" class="panel"><input type="hidden" name="_csrf" value="<?=spn1100_h(csrf_token())?>"><button name="action" value="restore" onclick="return confirm('Restore all canonical landing menu defaults?')">Restore All Menu Defaults</button></form></div><?php require __DIR__.'/../app/end.php';?>
